//! `Router::set_reroute_after_edits()`, which the port takes from the
//! Adaptagrams fork that libavoid-js builds on (Aksem/adaptagrams), against
//! the C++ (golden: `tests/reroute_after_edits/golden.txt`, regenerated by
//! `tools/oracle/reroute_after_edits.sh`).
//!
//! The scenes set checkpoints on connectors that have been routed and
//! delete connectors.  With the option off, the routes after every
//! transaction must match upstream exactly; with it on, they must match
//! upstream with the fork's two fixes applied
//! (`tools/oracle/reroute_after_edits.patch`).

mod scene_replay;

#[test]
fn reroute_after_edits_matches_cpp() {
    let golden = include_str!("reroute_after_edits/golden.txt");
    let (checked, affected) = scene_replay::check_off_on(golden, |r, on| r.set_reroute_after_edits(on));
    // The option must change routes in a fair share of the scenes checked.
    assert!(affected * 8 > checked, "the option changes only {affected} of {checked} scenes");
}
